// Chọn vùng chỉ chứa một dòng thời gian.
sleep(3);
var sampledAt = now();
var text = ocr(0.65, 0.15, 1, 0.4);
log("OCR: " + text);
var m = text.replace(/：/g, ":").match(/(?:^|[^0-9])(\d{1,2})\s*[:.;/]\s*(\d{2})(?!\d)/);
if (m && Number(m[2]) < 60) {
  var seconds = Number(m[1]) * 60 + Number(m[2]);
  var deadline = sampledAt + seconds * 1000;
  log("Thời gian: " + seconds + " giây");
  while (now() < deadline) {
    sleep(Math.min(1, (deadline - now()) / 1000));
  }
  log("Đến hạn; tìm lại nút và kiểm tra trước khi bấm");
} else {
  log("Không đọc được MM:SS hợp lệ");
}

